        id_tutor: tutor.id_tutor,
        nombre: tutor.nombre,
        materia: tutor.especialidad_materias,
        dia: h.dia_semana,
        hora_inicio: h.hora_inicio,
        hora_fin: h.hora_fin
      });

      indiceMateria++;
    });
  }
});

mensaje += "───────────────────\n✏️ *Para seleccionar una opción, simplemente responde con el número correspondiente.*";

// 6. Construimos el objeto final con la acción y la lista completa de opciones
const estructuraFinal = {
  accion: "crear_tutoria",
  opciones: opcionesDisponibles
};

// 7. Lo convertimos a string JSON listo para la celda de Google Sheets
const datosParcialesString = JSON.stringify(estructuraFinal);

// Retornamos el formato unificado para n8n
return [{
  json: {
    chat_id: chatId,
    texto_notificacion: mensaje.trim(),
    datos_parciales: datosParcialesString
  }
}];

// 1. Obtenemos la fila encontrada en el nodo 'Buscar por telegram_id' (o tu nodo de búsqueda de Sheets)
// NOTA: Asegúrate de que el nombre del nodo coincide exactamente con el tuyo, por ejemplo 'Buscar por telegram_id'
const filaGoogleSheets = $('Buscar por telegram_id').first().json;

// 2. Extraemos y parseamos el objeto JSON de datos_parciales
const textoJson = filaGoogleSheets.datos_parciales;
if (!textoJson) {
  throw new Error("La columna 'datos_parciales' está vacía.");
}
const datosParciales = JSON.parse(textoJson);

// 3. 🌟 CORRECCIÓN: Obtenemos el número de opción desde el nodo unificado de entrada 'Datos a json'
const respuestaUsuario = parseInt($('Obtener formato limpio').first().json?.mensaje?.toString()?.trim(), 10);

if (isNaN(respuestaUsuario)) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ Por favor, introduce únicamente el número de la opción elegida."
    }
  }];
}

// 4. Buscamos de forma exacta la opción que coincide con ese número
const opcionSeleccionada = datosParciales.opciones.find(o => parseInt(o.opcion_numero) === respuestaUsuario);

// Si el usuario puso un número que no estaba en la lista
if (!opcionSeleccionada) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ Opción no válida. Por favor, selecciona un número de la lista."
    }
  }];
}

// 🎯 ESTRATEGIA DE REDUCCIÓN: Creamos la estructura limpia para la celda de Google Sheets
const estructuraReducida = {
  accion: datosParciales.accion,
  ...opcionSeleccionada 
};

// 5. Retornamos los datos manteniendo la compatibilidad de tus textos de Telegram
return [{
  json: {
    error: false,
    chat_id: filaGoogleSheets.telegram_id || "",
    // Esto lo usará el nodo de Google Sheets para actualizar la sesión
    datos_parciales_limpios: JSON.stringify(estructuraReducida),

    // 🌟 AQUÍ ESTÁ LA MAGIA: Inyectamos las propiedades sueltas directamente en la raíz
    // para que {{ $json.materia }}, {{ $json.nombre }}, {{ $json.dia }}, etc. funcionen en tu Telegram
    opcion_numero: opcionSeleccionada.opcion_numero,
    id_tutor: opcionSeleccionada.id_tutor,
    nombre: opcionSeleccionada.nombre,
    materia: opcionSeleccionada.materia,
    dia: opcionSeleccionada.dia,
    hora_inicio: opcionSeleccionada.hora_inicio,
    hora_fin: opcionSeleccionada.hora_fin
  }
}];

