}

// 3. Recorremos los registros globales para calcular el ID numérico más alto
let maxIdNumerico = 0;
filasTutorias.forEach(item => {
  const tutoria = item.json;
  // Nos aseguramos de que id_tutoria exista y sea un texto válido antes de procesar
  if (tutoria && tutoria.id_tutoria && typeof tutoria.id_tutoria === 'string' && tutoria.id_tutoria.trim() !== "") {
    const numeroExtraido = parseInt(tutoria.id_tutoria.replace(/[^0-9]/g, ''), 10);
    if (!isNaN(numeroExtraido) && numeroExtraido > maxIdNumerico) {
      maxIdNumerico = numeroExtraido;
    }
  }
});

const nuevoNumero = maxIdNumerico + 1;
const nuevoIdTutoria = "TUTOR" + String(nuevoNumero).padStart(3, '0');

// 🎯 LÓGICA CORREGIDA: Como ya no hay una lista '.opciones', los datos están 
