// 1) Obtener fila de Sheets (ya validaste que existe)
const filaGoogleSheets = $('Buscar por id3').first().json;
const textoJson = filaGoogleSheets?.datos_parciales;

if (!textoJson) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ La columna 'datos_parciales' está vacía o no hay sesión activa.",
      datos_parciales_limpios: null
    }
  }];
}

// 2) Parsear datos_parciales (string -> objeto)
let datosParciales;
try {
  datosParciales = JSON.parse(textoJson);
} catch (e) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ No pude parsear 'datos_parciales' como JSON.",
      datos_parciales_limpios: null
    }
  }];
}

// 3) Obtener el texto/número desde el nodo Fields (según tu fiel formateado)
const fieldsJson = $('Obtener formato limpio').first().json;

// tu fiel formateado usa la clave: "mensaje"
const respuestaUsuarioRaw = fieldsJson?.mensaje ?? "";

const respuestaUsuario = parseInt(String(respuestaUsuarioRaw).trim(), 10);

if (Number.isNaN(respuestaUsuario)) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ Por favor, responde únicamente con el número de la tutoría que deseas cancelar.",
      datos_parciales_limpios: null
    }
  }];
}


// 4) Tomar opciones (deben existir)
const opciones = Array.isArray(datosParciales?.opciones) ? datosParciales.opciones : [];

if (opciones.length === 0) {
  return [{
    json: {
      error: true,
      mensaje: "⚠️ No encontré la lista de tutorías en 'datos_parciales.opciones'.",
      datos_parciales_limpios: null
    }
  }];
}

// 5) Buscar por opcion_numero (como en tu preview llega)
const opcionSeleccionada = opciones.find(
  (o) => o?.opcion_numero !== undefined && parseInt(o.opcion_numero, 10) === respuestaUsuario
);

// 6) Validación
if (!opcionSeleccionada) {
  return [{
    json: {
      error: true,
      mensaje: `⚠️ El número [${respuestaUsuario}] no corresponde a ninguna de tus tutorías activas.`,
      datos_parciales_limpios: null
    }
  }];
}

// 7) Estructura reducida para el update en Sheets
const estructuraReducida = {
  accion: datosParciales?.accion || "cancelar_tutoria",
  id_tutoria: opcionSeleccionada.id_tutoria,
  materia: opcionSeleccionada.materia,
  fecha: opcionSeleccionada.fecha,
  hora: opcionSeleccionada.hora,
  estado: "Cancelada"
};

// 8) Retorno final (mantengo nombres para que sigas mapeando)
return [{
  json: {
    error: false,
    chat_id: filaGoogleSheets?.telegram_id || "",

    datos_parciales_limpios: JSON.stringify(estructuraReducida),

    id_tutoria_a_cancelar: opcionSeleccionada.id_tutoria,
    materia_cancelada: opcionSeleccionada.materia,
    fecha_tutoria: opcionSeleccionada.fecha,
    hora_tutoria: opcionSeleccionada.hora,
    nuevo_estado: "Cancelada"
  }
}];

